function simpleGet (opts, cb) {
  opts = Object.assign({ maxRedirects: 10 }, typeof opts === 'string' ? { url: opts } : opts)
  cb = once(cb)

  if (opts.url) {
    const { hostname, port, protocol, auth, path } = url.parse(opts.url)
    delete opts.url
    if (!hostname && !port && !protocol && !auth) opts.path = path
    else Object.assign(opts, { hostname, port, protocol, auth, path })
  }

  const headers = { 'accept-encoding': 'gzip, deflate' }
  if (opts.headers) Object.keys(opts.headers).forEach(k => (headers[k.toLowerCase()] = opts.headers[k]))
  opts.headers = headers

  let body
  if (opts.body) {
    body = opts.json && !isStream(opts.body) ? JSON.stringify(opts.body) : opts.body
  } else if (opts.form) {
    body = typeof opts.form === 'string' ? opts.form : querystring.stringify(opts.form)
    opts.headers['content-type'] = 'application/x-www-form-urlencoded'
  }

  if (body) {
    if (!opts.method) opts.method = 'POST'
    if (!isStream(body)) opts.headers['content-length'] = Buffer.byteLength(body)
    if (opts.json && !opts.form) opts.headers['content-type'] = 'application/json'
  }
  delete opts.body; delete opts.form

  if (opts.json) opts.headers.accept = 'application/json'
  if (opts.method) opts.method = opts.method.toUpperCase()

  const protocol = opts.protocol === 'https:' ? https : http
  const req = protocol.request(opts, res => {
    if (opts.followRedirects !== false && res.statusCode >= 300 && res.statusCode < 400 && res.headers.location) {
      opts.url = res.headers.location
      delete opts.headers.host
      res.resume()

      if (opts.method === 'POST' && [301, 302].includes(res.statusCode)) {
        opts.method = 'GET'
        delete opts.headers['content-length']; delete opts.headers['content-type']
      }

      if (opts.maxRedirects-- === 0) return cb(new Error('too many redirects'))
      else return simpleGet(opts, cb)
    }

    const tryUnzip = typeof decompressResponse === 'function' && opts.method !== 'HEAD'
    cb(null, tryUnzip ? decompressResponse(res) : res)
  })
  req.on('timeout', () => {
    req.abort()
    cb(new Error('Request timed out'))
  })
  req.on('error', cb)

  if (isStream(body)) body.on('error', cb).pipe(req)
  else req.end(body)

  return req
}

function set(root, space, value) {
	var i,
		c,
		val,
		nextSpace,
		curSpace = root;

	space = parse(space);

	val = space.pop();

	for (i = 0, c = space.length; i < c; i++) {
		nextSpace = String(space[i]);

		if (
			nextSpace === '__proto__' ||
			nextSpace === 'constructor' ||
			nextSpace === 'prototype'
		) {
			return null;
		}

		if (isUndefined(curSpace[nextSpace])) {
			curSpace[nextSpace] = {};
		}

		curSpace = curSpace[nextSpace];
	}

	curSpace[val] = value;

	return curSpace;
}

function finish () {
    if (!that.disconnected && that.will) {
      that.broker.authorizePublish(that, that.will, function (err) {
        if (!err) {
          that.broker.publish(that.will, that, done)
        } else {
          done()
        }

        function done (err) {
          if (!err) {
            that.broker.persistence.delWill({
              id: that.id,
              brokerId: that.broker.id
            }, nop)
          }
        }
      })
      that.will = null
    }

    conn.removeAllListeners('error')
    conn.on('error', nop)

    if (that.broker.clients[that.id]) {
      that.broker.unregisterClient(that)
    }

    var state = that.conn._writableState
    var list = (state.getBuffer && state.getBuffer()) || state.buffer
    list.forEach(drainRequest)

    that.conn.emit('drain')
    that.conn.removeAllListeners('drain')

    if (conn.destroySoon) {
      conn.destroySoon()
    } if (conn.destroy) {
      conn.destroy()
    } else {
      conn.end()
    }

    if (typeof done === 'function') {
      done()
    }
  }

function fastifySwagger (fastify, opts, done) {
  let staticCSP = false
  if (opts.staticCSP === true) {
    const csp = fastify.swaggerCSP
    staticCSP = `default-src 'self'; base-uri 'self'; font-src 'self' https: data:; frame-ancestors 'self'; img-src 'self' data: validator.swagger.io; object-src 'none'; script-src 'self' ${csp.script.join(' ')}; script-src-attr 'none'; style-src 'self' https: ${csp.style.join(' ')}; upgrade-insecure-requests;`
  }
  if (typeof opts.staticCSP === 'string') {
    staticCSP = opts.staticCSP
  }
  if (typeof opts.staticCSP === 'object' && opts.staticCSP !== null) {
    staticCSP = ''
    Object.keys(opts.staticCSP).forEach(function (key) {
      const value = Array.isArray(opts.staticCSP[key]) ? opts.staticCSP[key].join(' ') : opts.staticCSP[key]
      staticCSP += `${key.toLowerCase()} ${value}; `
    })
  }

  if (typeof staticCSP === 'string' || typeof opts.transformStaticCSP === 'function') {
    fastify.addHook('onSend', function (request, reply, payload, done) {
      if (typeof staticCSP === 'string') {
        reply.header('content-security-policy', staticCSP.trim())
      }
      const header = reply.getHeader('content-security-policy')
      if (header && typeof opts.transformStaticCSP === 'function') {
        reply.header('content-security-policy', opts.transformStaticCSP(header))
      }
      done()
    })
  }

  const hooks = Object.create(null)
  if (opts.hooks) {
    const additionalHooks = [
      'onRequest',
      'preHandler'
    ]
    for (const hook of additionalHooks) {
      hooks[hook] = opts.hooks[hook]
    }
  }

  fastify.route({
    url: '/',
    method: 'GET',
    schema: { hide: true },
    ...hooks,
    handler: (req, reply) => {
      reply.redirect(getRedirectPathForTheRootRoute(req.raw.url))
    }
  })

  if (opts.theme) {
    const themePrefix = `${staticPrefix}/theme`
    if (opts.theme.css) {
      for (const cssFile of opts.theme.css) {
        fastify.route({
          url: `${themePrefix}/${cssFile.filename}`,
          method: 'GET',
          schema: { hide: true },
          ...hooks,
          handler: (req, reply) => {
            reply
              .header('content-type', 'text/css; charset=UTF-8')
              .send(cssFile.content)
          }
        })
      }
    }

    if (opts.theme.js) {
      for (const jsFile of opts.theme.js) {
        fastify.route({
          url: `${themePrefix}/${jsFile.filename}`,
          method: 'GET',
          schema: { hide: true },
          ...hooks,
          handler: (req, reply) => {
            reply
              .header('content-type', 'application/javascript; charset=utf-8')
              .send(jsFile.content)
          }
        })
      }
    }

    if (opts.theme.favicon) {
      for (const favicon of opts.theme.favicon) {
        fastify.route({
          url: `${themePrefix}/${favicon.filename}`,
          method: 'GET',
          schema: { hide: true },
          ...hooks,
          handler: (req, reply) => {
            reply
              .header('content-type', favicon.type)
              .send(favicon.content)
          }
        })
      }
    }
  }

  const indexHtmlContent = indexHtml(opts)

  fastify.route({
    url: `${staticPrefix}/index.html`,
    method: 'GET',
    schema: { hide: true },
    ...hooks,
    handler: (req, reply) => {
      reply
        .header('content-type', 'text/html; charset=utf-8')
        .send(indexHtmlContent)
    }
  })

  const swaggerInitializerContent = swaggerInitializer(opts)

  fastify.route({
    url: `${staticPrefix}/swagger-initializer.js`,
    method: 'GET',
    schema: { hide: true },
    ...hooks,
    handler: (req, reply) => {
      reply
        .header('content-type', 'application/javascript; charset=utf-8')
        .send(swaggerInitializerContent)
    }
  })

  const hasTransformSpecificationFn = typeof opts.transformSpecification === 'function'
  const shouldCloneSwaggerObject = opts.transformSpecificationClone ?? true
  const transformSpecification = opts.transformSpecification
  fastify.route({
    url: '/json',
    method: 'GET',
    schema: { hide: true },
    ...hooks,
    handler: hasTransformSpecificationFn
      ? shouldCloneSwaggerObject
        ? function (req, reply) {
          reply.send(transformSpecification(rfdc(fastify.swagger()), req, reply))
        }
        : function (req, reply) {
          reply.send(transformSpecification(fastify.swagger(), req, reply))
        }
      : function (req, reply) {
        reply.send(fastify.swagger())
      }
  })

  fastify.route({
    url: '/yaml',
    method: 'GET',
    schema: { hide: true },
    ...hooks,
    handler: hasTransformSpecificationFn
      ? shouldCloneSwaggerObject
        ? function (req, reply) {
          reply
            .type('application/x-yaml')
            .send(yaml.stringify(transformSpecification(rfdc(fastify.swagger()), req, reply)))
        }
        : function (req, reply) {
          reply
            .type('application/x-yaml')
            .send(yaml.stringify(transformSpecification(fastify.swagger(), req, reply)))
        }
      : function (req, reply) {
        reply
          .type('application/x-yaml')
          .send(fastify.swagger({ yaml: true }))
      }
  })

  fastify.register(fastifyStatic, {
    root: opts.baseDir || path.join(__dirname, '..', 'static'),
    prefix: staticPrefix,
    decorateReply: false
  })

  if (opts.baseDir) {
    fastify.register(fastifyStatic, {
      root: opts.baseDir,
      serve: false
    })

    fastify.route({
      url: '/*',
      method: 'GET',
      schema: { hide: true },
      ...hooks,
      handler: function (req, reply) {
        const file = req.params['*']
        reply.sendFile(file)
      }
    })
  }

  done()
}

function set(target, path, value) {

  let currentTarget = target;

  forEach(path, function(key, idx) {

    if (key === '__proto__') {
      throw new Error('illegal key: __proto__');
    }

    let nextKey = path[idx + 1];
    let nextTarget = currentTarget[key];

    if (isDefined(nextKey) && isNil(nextTarget)) {
      nextTarget = currentTarget[key] = isNaN(+nextKey) ? {} : [];
    }

    if (isUndefined(nextKey)) {
      if (isUndefined(value)) {
        delete currentTarget[key];
      } else {
        currentTarget[key] = value;
      }
    } else {
      currentTarget = nextTarget;
    }
  });

  return target;
}

