_format(value) {
    if (['boolean', 'number'].includes(typeof value)) {
      return `${value}`;
    } else if ('string' === typeof value) {
      if (value.includes('\'')) {
        throw Error('Argument must not contain single quote "\'"');
      } else if (/^[0-9a-z-=/~.:]+$/i.test(value)) {
        return `${value}`;
      }
      return `'${value}'`;
    }
    throw Error(`Invalid argument type: '${typeof value}'`);
  }

