function escapeArgBash(arg, interpolation, quoted) {
  let result = arg.replace(/\0/gu, "");

  if (interpolation) {
    result = result
      .replace(/\\/gu, "\\\\")
      .replace(/\n/gu, " ")
      .replace(/(^|\s)(~|#)/gu, "$1\\$2")
      .replace(/(\*|\?)/gu, "\\$1")
      .replace(/([$&;|])/gu, "\\$1")
      .replace(/([()<>])/gu, "\\$1")
      .replace(/(["'`])/gu, "\\$1")
      .replace(/\{(?=([^,.]*(?:,|\.)[^]*?)\})/gu, "\\{")
      .replace(/(?<==(?:[^]*?:)?)(~)(?=[\s+\-/0:=]|$)/gu, "\\$1");
  } else if (quoted) {
    result = result.replace(/'/gu, `'\\''`);
  }

  return result;
}

